mapper.select:
SELECT po.id,po.status,po.ordered_at,po.expected_at,s.name supplier_name,w.name warehouse_name
FROM purchase_order po JOIN supplier s ON s.id=po.supplier_id JOIN warehouse w ON w.id=po.warehouse_id

  po.status=#{status}
  AND po.id < #{beforeId}

ORDER BY po.id DESC LIMIT #{limit}

SELECT r.id,r.order_id,r.customer_id,r.reason,r.status,r.refund_amount,r.requested_at,c.name customer_name
FROM return_order r JOIN customer c ON c.id=r.customer_id

  r.status=#{status}
  AND r.id < #{beforeId}

ORDER BY r.id DESC LIMIT #{limit}

SELECT id,order_no,customer_id,status,channel,ordered_at,total_amount FROM sales_order

  customer_id=#{customerId}
  AND status=#{status}
  AND id < #{beforeId}

ORDER BY id DESC LIMIT #{limit}

SELECT o.*,c.name customer_name,w.name warehouse_name
FROM sales_order o JOIN customer c ON c.id=o.customer_id JOIN warehouse w ON w.id=o.warehouse_id
WHERE o.id=#{id}

SELECT p.id,p.name,p.status,c.name category_name,b.name brand_name
FROM product p JOIN category c ON c.id=p.category_id JOIN brand b ON b.id=p.brand_id
WHERE p.id > #{afterId}
AND p.category_id=#{categoryId}
ORDER BY p.id LIMIT #{limit}

SELECT iv.sku_id,s.code,s.price,iv.available_qty,iv.reserved_qty,iv.reorder_point
FROM inventory iv JOIN sku s ON s.id=iv.sku_id
WHERE iv.warehouse_id=#{warehouseId} AND iv.sku_id > #{afterSkuId}
ORDER BY iv.sku_id LIMIT #{limit}

SELECT po.*,s.name supplier_name,w.name warehouse_name
FROM purchase_order po JOIN supplier s ON s.id=po.supplier_id JOIN warehouse w ON w.id=po.warehouse_id
WHERE po.id=#{id}
